BASE_SEED = 42
from ray import tune
import optax

def _define_hyperparameters():
    return {
        "learning_rate": tune.choice([4e-4]),
        "entropy_coef": tune.choice([0.01]),
        "value_loss_coef": tune.choice([0.5]),
        # Add the missing CNN feature hyperparameters required by default_create_network
        "cnn_features_1": tune.choice([32]),
        "cnn_features_2": tune.choice([64]),
        "lstm_features": tune.choice([256])  # Including this for completeness, though not used by default CNN
    }

def create_optimizer(learning_rate: float = 4e-4):
    # AdamW with mild weight decay; keep global gradient clipping = 1.0
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=2e-4),
    )
